// KPIs operativos de las empresas 101-300 del universo (capa 5), fusionados en KPI_DEFS (kpis.ts).
// Elegidos leyendo el último 8-K de resultados de cada una (noviembre de 2026). Para ir rápido con
// tantas empresas: plantillas por tipo de negocio y `co()`, que crea un gráfico por KPI salvo que se
// agrupen (`groups`). Cada hint pide la cifra "solo si aparece": si un comunicado no la trae, no hay dato.
import type { CompanyKpis, KpiDef, KpiChart } from "./kpis";
import { usd, lvl, gr, dol, num, mil, ch, guide, guideChart, gmG, gmN, opmN, fcf, bank, pharma, type R } from "./kpisMore";

type Group = [id: string, en: string, es: string, type: KpiChart["type"], keys: string[], extra?: Partial<KpiChart>];

/** Empresa con un gráfico por KPI (barras para flujos en dinero o unidades, línea para el resto), salvo los agrupados. */
export function co(kpis: KpiDef[], groups: Group[] = [], extra: Partial<CompanyKpis> = {}): CompanyKpis {
  const charts: KpiChart[] = [];
  const used = new Set<string>();
  const has = (k: string) => kpis.some((d) => d.key === k);
  if (has("guidance_next")) {
    charts.push(guideChart());
    used.add("guidance_next");
  }
  for (const [id, en, es, type, keys, more] of groups) {
    const ks = keys.filter((k) => has(k) || k === "revenue");
    if (!ks.length) continue;
    charts.push(ch(id, en, es, type, ks, more ?? {}));
    ks.forEach((k) => used.add(k));
  }
  const gm = ["gm_gaap", "gm_nongaap"].filter(has).filter((k) => !used.has(k));
  if (gm.length) {
    charts.push(ch("gm", gm.length === 2 ? "Gross margin (GAAP / non-GAAP)" : kpis.find((d) => d.key === gm[0])!.en, gm.length === 2 ? "Margen bruto (GAAP / no GAAP)" : kpis.find((d) => d.key === gm[0])!.es, "line", gm));
    gm.forEach((k) => used.add(k));
  }
  for (const d of kpis) {
    if (used.has(d.key)) continue;
    const bar = d.kind === "flow" && ["$M", "n", "M", "$"].includes(d.unit);
    const id = charts.some((c) => c.id === d.key) ? `${d.key}_k` : d.key; // sin chocar con un grupo del mismo nombre
    charts.push(ch(id, d.en, d.es, bar ? "bar" : "line", [d.key]));
  }
  return { from: "2023-01-01", kpis, charts, ...extra };
}

// ------------------------------------------------------------------ piezas comunes
const opmG = () => lvl("opm_gaap", "GAAP operating margin", "Margen operativo GAAP", "GAAP operating margin of the quarter", [-100, 100]);
const orders = (label = "Orders", range: R = [10, 500000]) => usd("orders", label, "Pedidos", `${label} received in the quarter (total company)`, range);
const backlog = (label = "Backlog", range: R = [10, 2000000]) => usd("backlog", label, "Cartera de pedidos", `${label} at quarter end (total company), only if stated`, range, "stock");
const organic = (label = "Organic revenue growth") => gr("organic", label, "Crecimiento orgánico", `${label} (core/organic, excluding currency and acquisitions)`);
const adjOpm = (label = "Adjusted operating margin") => lvl("opm_adj", label, "Margen operativo ajustado", `${label} of the quarter (total company)`, [-100, 100]);
const adjEbitda = (label = "Adjusted EBITDA", range: R = [-5000, 200000]) => usd("adj_ebitda", label, "EBITDA ajustado", `${label} for the quarter (total company)`, range);
const adjEps = (label = "Adjusted EPS") => dol("adj_eps", label, "BPA ajustado", `${label} (non-GAAP / operating diluted earnings per share) for the QUARTER`, [-50, 200], "flow");
const crpo = () => usd("crpo", "Current remaining performance obligations (cRPO)", "Cartera contratada a 12 meses (cRPO)", "Current remaining performance obligations (cRPO) at quarter end, only if stated", [10, 500000], "stock");
const rpo = () => usd("rpo", "Remaining performance obligations (RPO)", "Cartera contratada (RPO)", "Total remaining performance obligations (RPO) at quarter end, only if stated", [10, 1000000], "stock");
const subGr = () => gr("sub_growth", "Subscription revenue growth", "Crecimiento de ingresos por suscripción", "Subscription revenue growth");
const arr = (label = "Annual recurring revenue (ARR)") => usd("arr", label, "Ingresos recurrentes anuales (ARR)", `${label} at quarter end, only if stated as a dollar amount`, [10, 500000], "stock");

// Plantillas
const semi = (extra: KpiDef[] = [], groups: Group[] = []) => co([guide(), gmG(), gmN(), opmN(), fcf(), ...extra], groups);
const saas = (extra: KpiDef[] = [], groups: Group[] = [], withGuide = true) =>
  co([...(withGuide ? [guide()] : []), subGr(), crpo(), rpo(), opmN(), fcf(), ...extra], [["rpo", "Remaining performance obligations (current / total)", "Cartera contratada (12 meses / total)", "line", ["crpo", "rpo"]], ...groups]);
const industrial = (extra: KpiDef[] = [], groups: Group[] = []) => co([orders(), backlog(), organic(), adjOpm(), fcf(), ...extra], groups);
const ofYoy = (key: string, en: string, es: string, hint: string) => gr(key, en, es, hint);

// Eléctricas: BPA ajustado del trimestre + lo que den
const utility = (epsLabel: string, extra: KpiDef[] = []) => co([adjEps(epsLabel), ...extra]);
// REIT: FFO/AFFO por acción del trimestre + lo que den
const reit = (ffoLabel: string, extra: KpiDef[] = []) =>
  co([dol("ffo_ps", ffoLabel, ffoLabel.replace("per share", "por acción"), `${ffoLabel} (diluted) for the QUARTER`, [0.05, 50], "flow"), ...extra]);
// Petroleras de exploración y producción
const ep = (extra: KpiDef[] = []) =>
  co([num("production", "Total production (thousand BOE/day)", "Producción total (miles de barriles equivalentes/día)", "Total net production in thousand barrels of oil equivalent per day (MBOE/d or MBoed; e.g. '1,668,000 Boe per day' -> 1668)", [100, 5000], "avg"), num("oil_production", "Oil production (thousand bbl/day)", "Producción de petróleo (miles de barriles/día)", "Crude oil (and condensate) production in thousand barrels per day", [50, 3000], "avg"), usd("capex", "Capital expenditures", "Inversiones (capex)", "Capital expenditures (cash capex or accrued, as headline) for the quarter", [100, 20000]), fcf(), ...extra],
    [["prod", "Production (total / oil)", "Producción (total / petróleo)", "line", ["production", "oil_production"]]]);

